<script>
const rcStore=@json(route('review-cycles-store')),rcUpdate=@json(route('review-cycles-update','__ID__'));function editRC(x){let d=JSON.parse(atob(x)),f=rcForm;f.action=rcUpdate.replace('__ID__',d.id);rcMethod.innerHTML='<input type="hidden" name="_method" value="PUT">';['name','frequency','description'].forEach(k=>f.elements[k].value=d[k]||'');f.elements.status.value=d.status?1:0;rcTitle.textContent='Edit Review Cycle';rcSave.textContent='Update Review Cycle';rcCancel.style.display='block';window.scrollTo({top:0,behavior:'smooth'})}function resetRC(){let f=rcForm;f.reset();f.action=rcStore;rcMethod.innerHTML='';rcTitle.textContent='Add New Review Cycle';rcSave.textContent='Add Review Cycle';rcCancel.style.display='none';f.querySelectorAll('.rc-error').forEach(x=>x.remove());f.querySelectorAll('.rc-invalid').forEach(x=>x.classList.remove('rc-invalid'))}function moreRC(b){let d=b.parentElement.querySelector('[data-description]'),open=b.dataset.open==='1';d.textContent=open?atob(b.dataset.short):atob(b.dataset.full);b.dataset.open=open?'0':'1';b.textContent=open?'⌄ Show more':'⌃ Show less'}document.addEventListener('DOMContentLoaded',()=>{let f=rcForm,rules={name:e=>!e.value.trim()?'Review Cycle Name is required':e.value.trim().length<2?'Review Cycle Name must be at least 2 characters':'',frequency:e=>!e.value?'Frequency is required':'',status:e=>e.value===''?'Status is required':''};function validate(e){let msg=rules[e.name](e),x=e.parentElement.querySelector('.rc-error');if(!x){x=document.createElement('div');x.className='rc-error';e.after(x)}e.classList.toggle('rc-invalid',!!msg);x.textContent=msg;x.style.display=msg?'block':'none';return !msg}Object.keys(rules).forEach(k=>['input','change','blur'].forEach(v=>f.elements[k].addEventListener(v,()=>validate(f.elements[k]))));f.onsubmit=e=>{let first;Object.keys(rules).forEach(k=>{if(!validate(f.elements[k])&&!first)first=f.elements[k]});if(first){e.preventDefault();first.focus()}};document.querySelectorAll('.rc-delete').forEach(x=>x.onsubmit=e=>{if(x.dataset.ok)return;e.preventDefault();Swal.fire({title:'Delete review cycle?',text:'This action cannot be undone.',showCancelButton:true,confirmButtonText:'Delete',confirmButtonColor:'#f1416c'}).then(r=>{if(r.isConfirmed){x.dataset.ok=1;x.submit()}})})});
</script>@endsection
